PRAGMA foreign_keys = ON;
CREATE TABLE subjects (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#5965e8',description TEXT DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE topics (id INTEGER PRIMARY KEY AUTOINCREMENT,subject_id INTEGER NOT NULL,parent_id INTEGER,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','learning','review','confident')),description TEXT DEFAULT '',notes TEXT DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE notes (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,content TEXT NOT NULL DEFAULT '',topic_id INTEGER,favorite INTEGER DEFAULT 0,is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE flashcards (id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER NOT NULL,question TEXT NOT NULL,answer TEXT NOT NULL,difficulty TEXT DEFAULT 'normal',tags TEXT DEFAULT '',correct_count INTEGER DEFAULT 0,wrong_count INTEGER DEFAULT 0,last_result TEXT,is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE CASCADE);
CREATE TABLE quiz_questions (id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER NOT NULL,type TEXT NOT NULL,question TEXT NOT NULL,options_json TEXT,answer_json TEXT NOT NULL,explanation TEXT DEFAULT '',difficulty TEXT DEFAULT 'normal',FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT,score INTEGER NOT NULL,total INTEGER NOT NULL,details_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT DEFAULT '',due_date TEXT NOT NULL,priority TEXT DEFAULT 'normal',status TEXT DEFAULT 'open',category TEXT DEFAULT 'Allgemein',subject_id INTEGER,topic_id INTEGER,is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,event_date TEXT NOT NULL,type TEXT NOT NULL,subject_id INTEGER,topic_id INTEGER,is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE lessons (id INTEGER PRIMARY KEY AUTOINCREMENT,subject_id INTEGER,topic_id INTEGER,lesson_date TEXT NOT NULL,title TEXT NOT NULL,notes TEXT DEFAULT '',homework TEXT DEFAULT '',is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE grades (id INTEGER PRIMARY KEY AUTOINCREMENT,subject_id INTEGER NOT NULL,name TEXT NOT NULL,date TEXT NOT NULL,grade REAL NOT NULL CHECK(grade BETWEEN 1 AND 6),weight REAL DEFAULT 1,comment TEXT DEFAULT '',is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE departments (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,start_date TEXT,end_date TEXT,description TEXT DEFAULT '',technologies TEXT DEFAULT '',contact TEXT DEFAULT '',is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activities (id INTEGER PRIMARY KEY AUTOINCREMENT,department_id INTEGER NOT NULL,topic_id INTEGER,activity_date TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',programs TEXT DEFAULT '',duration_minutes INTEGER,is_demo INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE CASCADE,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE training_weeks (id INTEGER PRIMARY KEY AUTOINCREMENT,year INTEGER NOT NULL,week INTEGER NOT NULL,status TEXT DEFAULT 'draft',UNIQUE(year,week));
CREATE TABLE training_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,week_id INTEGER NOT NULL,weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 5),entry_type TEXT NOT NULL,content TEXT NOT NULL,minutes INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(week_id,weekday),FOREIGN KEY(week_id) REFERENCES training_weeks(id) ON DELETE CASCADE);
CREATE TABLE files (id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,subject_id INTEGER,name TEXT NOT NULL,object_key TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE INDEX idx_topics_subject ON topics(subject_id);CREATE INDEX idx_tasks_due ON tasks(due_date,status);CREATE INDEX idx_events_date ON events(event_date);CREATE INDEX idx_notes_topic ON notes(topic_id);CREATE INDEX idx_flashcards_topic ON flashcards(topic_id);
